import{_ as s}from"./chunks/tcp_viewer_rscene_forest.VzSZQzKe.js";import{_ as r,o as a,c as i,a5 as t}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Rscene Server","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/rscene_server.md","filePath":"sections/examples/server/rscene_server.md"}'),n={name:"sections/examples/server/rscene_server.md"};function o(c,e,l,h,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="server-example-rscene-server" tabindex="-1">Server Example: Rscene Server <a class="header-anchor" href="#server-example-rscene-server" aria-label="Permalink to &quot;Server Example: Rscene Server&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Serves a RaiSim Engine scene (<code>.rscene</code>) to the rayrai TCP viewer. <code>raisim::World</code> builds the physics from the file, and <code>RaisimServer</code> streams its bodies. The viewer reads the same file and draws everything else the scene shows: visual-only objects, foliage, lights, the sky and the terrain textures. The result matches what <a href="./../rayrai/rayrai_forest_from_rscene.html">Rayrai Example: Forest From .rscene</a> renders in-process. The example serves the rayrai forest, <code>rsc/forest/rayrai_forest.rscene</code>.</p><figure><img src="'+s+`" alt="rayrai TCP viewer showing the forest scene served by rscene_server"><figcaption>The TCP viewer connected to <code>rscene_server</code>.</figcaption></figure><p><em>The viewer&#39;s icons are UIcons by Flaticon, credited in <a href="./../../AssetCredits.html#tcp-viewer-icons">Asset Credits</a>.</em></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rscene_server</code>. The source is <code>examples/src/server/visualization/rscene_server.cpp</code>. The target is skipped when the installed raisim cannot share scene files (<code>raisim/server/SceneFileServer.hpp</code>, new in v2.8.0).</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Start the viewer, then run the build-tree example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rscene_server</span></span></code></pre></div><p>On Windows, run <code>rscene_server.exe</code> instead.</p><h2 id="scene-files-on-another-computer" tabindex="-1">Scene files on another computer <a class="header-anchor" href="#scene-files-on-another-computer" aria-label="Permalink to &quot;Scene files on another computer&quot;">​</a></h2><p>A viewer that reaches the server through a non-loopback address asks before inspecting the server&#39;s paths or downloading files, even on the server&#39;s computer, unless it already has the scene&#39;s files. After consent, matching files at the server&#39;s paths or in resource directories are copied into the scene directory (<code>~/.raisim/scenes</code>), so later connections find them without asking; immutable cached files can be reused. Only missing files are downloaded from the server. The forest scene&#39;s files total about 430 MB. <a href="./../../RayraiTcpViewer.html#raisim-engine-scenes">RaiSim Engine scenes</a> describes the lookup and the prompt.</p><p>To accept a viewer from another computer, the server must listen on all interfaces. Add this before <code>launchServer()</code>:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setBindLoopbackOnly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>server.setSceneFileSharing(false)</code> keeps the files on the server. A remote viewer then shows only the streamed bodies.</p>`,16)])])}const f=r(n,[["render",o]]);export{u as __pageData,f as default};
